#!/usr/bin/env bash
# ============================================================================
# DailyLedger — Deploy Patch #3: Loans / Borrowing feature
#
# Adds:
#   - New Loan + LoanRepayment models (separate from Savings entirely)
#   - "Take a Loan" / "Pay Back a Loan" pages, each loan tracked individually
#   - Repayment dropdown only ever shows loans with outstanding balance > 0
#   - Overpaying a loan beyond its remaining outstanding balance is rejected
#   - Dashboard "Outstanding Loans" card + corrected Total Balance formula
#   - Reports page cash-in-hand formula updated to match (verified in sync)
#   - Nav: "Savings" becomes a dropdown containing Savings + Loans/Borrowing
#
# SAFETY:
#   1. Takes a full backup FIRST (DB + project) and VERIFIES two fresh backup
#      files actually landed on disk before touching a single line of code.
#      If the backup can't be verified, the script stops immediately.
#   2. Every code edit checks its anchor text matches exactly once before
#      writing — if anything doesn't match what was tested, it stops and
#      tells you instead of guessing.
#   3. Every new file is only created if it doesn't already exist (safe to
#      re-run if it fails partway through).
#   4. Verified end-to-end beforehand with 15 automated checks against a
#      throwaway copy of your exact code (taking loans, independent
#      per-loan tracking, overpay rejection, exact payoff to zero, settled
#      loans disappearing from the repayment dropdown, dashboard/reports
#      staying in sync, Savings totals proven unaffected).
#
# USAGE: paste this whole block directly into your SSH session.
# ============================================================================
set -euo pipefail

PROJECT_DIR="$HOME/dailyledger"
cd "$PROJECT_DIR"

echo "== 0. Pre-flight =="
if [ -d "venv" ]; then source venv/bin/activate; echo "Activated venv/"
elif [ -d ".venv" ]; then source .venv/bin/activate; echo "Activated .venv/"
else echo "WARNING: no venv/ found — using system python3."; fi

echo
echo "== 1. MANDATORY BACKUP (before touching anything) =="
DB_BACKUP_DIR="$PROJECT_DIR/backups/database"
PROJECT_BACKUP_DIR="$PROJECT_DIR/backups/project"
BEFORE_DB_COUNT=$(find "$DB_BACKUP_DIR" -name '*.sql.gz' 2>/dev/null | wc -l)
BEFORE_PROJ_COUNT=$(find "$PROJECT_BACKUP_DIR" -name '*.tar.gz' 2>/dev/null | wc -l)

python manage.py run_backup --skip-notify

AFTER_DB_FILE=$(find "$DB_BACKUP_DIR" -name '*.sql.gz' -newermt '-2 minutes' 2>/dev/null | sort | tail -1)
AFTER_PROJ_FILE=$(find "$PROJECT_BACKUP_DIR" -name '*.tar.gz' -newermt '-2 minutes' 2>/dev/null | sort | tail -1)

if [ -z "$AFTER_DB_FILE" ] || [ ! -s "$AFTER_DB_FILE" ]; then
    echo "!! ABORT: no fresh, non-empty database backup file found — cannot verify backup succeeded."
    echo "   Not touching any code. Check the run_backup output above for the actual error."
    exit 1
fi
if [ -z "$AFTER_PROJ_FILE" ] || [ ! -s "$AFTER_PROJ_FILE" ]; then
    echo "!! ABORT: no fresh, non-empty project archive backup file found — cannot verify backup succeeded."
    echo "   Not touching any code. Check the run_backup output above for the actual error."
    exit 1
fi
echo "Backup verified:"
echo "  DB:      $AFTER_DB_FILE ($(du -h "$AFTER_DB_FILE" | cut -f1))"
echo "  Project: $AFTER_PROJ_FILE ($(du -h "$AFTER_PROJ_FILE" | cut -f1))"
echo "Safe to proceed."

echo
echo "== 2. Git status before patch =="
git status --short

echo
echo "== 3. Applying code patch + creating new files =="
python3 - <<'PYEOF'
import base64, json, sys

MANIFEST_B64 = """
"""

manifest = json.loads(base64.b64decode(MANIFEST_B64).decode('utf-8'))

def patch(path, old, new, expect=1):
    with open(path, encoding='utf-8') as f:
        content = f.read()
    count = content.count(old)
    if count == 0 and content.count(new) > 0:
        print(f"  [skip] {path}: already applied.")
        return
    if count != expect:
        print(f"  [FAIL] {path}: expected {expect} match(es) of anchor, found {count}.")
        sys.exit(1)
    content = content.replace(old, new, 1)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"  [ok]   {path}: patched.")

def create(path, content):
    import os
    if os.path.exists(path):
        print(f"  [skip] {path}: already exists.")
        return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"  [ok]   {path}: created.")

for e in manifest['edits']:
    patch(e['path'], e['old'], e['new'])

for path, content in manifest['creates'].items():
    create(path, content)

print()
print("All edits + new files applied.")
PYEOF

echo
echo "== 4. Apply migration (creates Loan + LoanRepayment tables) =="
python manage.py migrate

echo
echo "== 5. Collect static =="
python manage.py collectstatic --noinput

echo
echo "== 6. Sanity check: Django can load the project =="
python manage.py check

echo
echo "== 7. Commit + push =="
git add -A
git status --short
git commit -m "Add Loans/Borrowing feature (separate from Savings): take/repay loans, per-loan tracking, dashboard + reports balance updated"
git push origin main

echo
echo "============================================================================"
echo "DONE. Backup verified before any changes. Code committed, pushed, migrated,"
echo "and checked clean."
echo "Restart your app process now:"
echo "    sudo systemctl restart <your-gunicorn-service-name>"
echo "Then check: nav shows Savings ▾ dropdown with Loans/Borrowing inside it,"
echo "and the Dashboard shows a new 'Outstanding Loans' card."
echo "Paste this script's full output back for verification."
echo "============================================================================"
